\label{flux:thm:ideal}

There exist universal constants \(c_0,c,C>0\) and a fixed
\(\rho_\star\in(0,1)\), independent of all problem parameters, such that, if
\(\beta\eta\le c_0\), then every integer
\(n_{\mathrm{blk}}\ge \frac{C}{\sqrt{\alpha\eta}}\sqrt{\log\frac{\mathrm{e}}{\alpha\eta}}\) satisfies, for every
\(\nu\ll\Pi_\eta\) and every nonnegative integer \(J\),
\begin{equation}
 \chi^2(\nu K_{\eta,\rho}^{J n_{\mathrm{blk}}}\Vert\Pi_\eta)
 \le \mathrm{e}^{-J}\chi^2(\nu\Vert\Pi_\eta).
 \label{flux:eq:ideal-contraction}
\end{equation}

\label{flux:thm:complexity}
Under \cref{ass:target}, let \(0<\varepsilon<1/4\), \(\Delta\ge1\), and let
\(\nu_0\) be an initial position law satisfying
\(D_2(\nu_0\Vert\pi)\le\Delta\).  There exist universal numerical constants
\(c,C>0\), independent of \(d,\kappa,\Delta,\varepsilon\), such that the following
choice is valid:


\begin{equation}
 L=\Delta+\log\tfrac{Cd\kappa}{\varepsilon},\qquad
 \eta=\tfrac{c}{\beta(\sqrt{dL}+L)}.
 \label{flux:eq:eta-final}
\end{equation}
Initialize \(X_0\sim\nu_0\) and
\(Y_0\mid X_0\sim\mathcal N(X_0,\eta I_d)\).  Then run
\cref{alg:reflected-proximal-overview} with the accelerated branch in
\cref{alg:flux-half-turn}, using the approximate RGO and capped Poisson clock
specified in \cref{flux:app:implementation}.  Its output distribution
\(\widehat\nu\) satisfies \(\operatorname{TV}(\widehat\nu,\pi)\le\varepsilon\).  Writing
\(N_{\mathrm{qry}}\) for its total number of oracle queries,


\begin{equation}
 \mathbb E N_{\mathrm{qry}}
 \le C\sqrt\kappa\,(d+L)^{1/4}L^{3/4}
       \left(\Delta+\log\tfrac4\varepsilon\right)\log(\mathrm{e}\kappa L).
 \label{flux:eq:complexity}
\end{equation}
In particular, a constant-\(D_2\) warm start requires
\(\widetilde O(\sqrt\kappa d^{1/4})\) expected oracle queries.

\label{thm:persistent-contraction}
There exist universal constants \(c_0,C>0\) and a fixed \(c_\rho>0\), independent of all problem parameters, such that the following holds.  If \(0<\eta\le c_0/\beta\), set \(\rho=c_\rho g\sqrt{\ell_g}\) and suppose \(\rho\le1/4\).  Then every integer \(n_{\mathrm{blk}}\ge C\sqrt{\ell_g}/g\) satisfies, for every \(\nu\ll\widehat\Pi_\eta=\Pi_\eta\otimes\gamma_d\) and every nonnegative integer \(J\),
\begin{equation}
 \chi^2(\nu K_{\mathrm{per}}^{J n_{\mathrm{blk}}}
 \|\widehat\Pi_\eta)
 \le\mathrm{e}^{-J}\chi^2(\nu\|\widehat\Pi_\eta).
 \label{eq:persistent-ideal-contraction}
\end{equation}
Consequently, initialize \(X_0\sim\nu_0\), \(Y_0\mid X_0\sim\mathcal N(X_0,\eta I_d)\), and independently \(P_0\sim\gamma_d\). Suppose \(D_2(\nu_0\Vert\pi)\le\Delta\). For \(\varepsilon\le1/2\), one obtains \(\operatorname{TV}(\operatorname{Law}(X_n),\pi)\le\varepsilon\) if
\begin{equation}
 n\ge\tfrac{C{\ell_g}^{1/2}}g
       \left(\Delta+\log\tfrac4\varepsilon\right).
 \label{eq:persistent-iterations}
\end{equation}

\label{thm:warm-removal-distributional}
\label{thm:warm-removal-cold}
\emph{(i) Finite-divergence input.}
Suppose a sample from an initial law \(\nu_0\) is available and the known
number \(B\ge1\) satisfies \(D_2(\nu_0\Vert\pi)\le B\).  For every
\(0<\varepsilon<1/4\), the wrapper using either reflected sampler as its final stage
returns an output law \(\widehat\nu\) with
\(\operatorname{TV}(\widehat\nu,\pi)\le\varepsilon\).  If \(N_{\mathrm{qry}}\) is the total number
of oracle queries, then
\begin{equation}
 \mathbb E N_{\mathrm{qry}}
 \le\widetilde O(
 \min\{
  \sqrt\kappa B(\sqrt{dB}+B)^{1/2},
  \Psi(\kappa,d)\log(\mathrm{e} B)
 \}).
 \label{eq:warm-removal-distributional-cost}
\end{equation}
If \(B\) is polynomially bounded in \(d,\kappa,1/\varepsilon\), this is at most
\(\widetilde O(\kappa^{6/7}d^{1/4})\).

\smallskip
\emph{(ii) Supplied point.}
Given \(x_0\in\mathbb R^d\) and \(0<\varepsilon<1/4\), let \(x_*\) be the minimizer of \(V\), define
\(\log_+(t)=\max\{1,\log t\}\), and set
\(Q_{\mathrm{loc}}=\sqrt\kappa\log_+[\kappa\{2+\sqrt\beta
\lVertx_0-x_*\rVert\}]\).  An implementable algorithm returns an output law
\(\widehat\nu\) with \(\operatorname{TV}(\widehat\nu,\pi)\le\varepsilon\) and
\begin{equation}
 \mathbb E N_{\mathrm{qry}}
 \le\widetilde O(Q_{\mathrm{loc}}+\Psi(\kappa,d))
 \le\widetilde O(
 Q_{\mathrm{loc}}+\kappa^{6/7}d^{1/4}).
 \label{eq:warm-removal-cold-cost}
\end{equation}

\label{flux:prop:weighted-affine}
\label{prop:flux-main-antipode}
There is a universal \(C\) such that, whenever \(s=\beta\eta\le1/2\),
the normalized-coordinate position kernel \(F_y^w\) of
\cref{alg:flux-half-turn} satisfies,
uniformly in \(y,u\in\mathbb R^d\),
\begin{equation}
 \lVert(I+F_y^w)\ell_{u,y}\rVert_{L^2(q_y^w)}^2
 \le Cs\,u^\mathrm{T}(I-\Sigma_y)u,
 \qquad \ell_{u,y}(w)=u^\mathrm{T}(w-\bar w_y).
 \label{flux:eq:weighted-halfturn}
\end{equation}

\label{flux:prop:ideal-L2}
There are universal constants \(c,C>0\) such that, when \(s\le c\) and
\(\rho\asymp\sqrt{a\log(\mathrm{e}/a)}\), the ideal chain satisfies
\[
 \lVert\mathsf K^n\rVert_{L^2_0(\Pi_\eta)\to L^2_0(\Pi_\eta)}
 \le \sqrt3\exp\left\{-\frac{cn\sqrt a}
                              {\sqrt{\log(\mathrm{e}/a)}}\right\}.
\]

\label{flux:prop:global-halfturn}
For sufficiently small universal \(s\) and every
\(v\in\mathcal H_Y\),
\begin{equation}
 \lVert(I+\mathsf F_Q)\mathsf Vv\rVert^2
 \le C\log(\mathrm{e}/\gamma_a)\lVert\Gamma v\rVert^2.
 \label{flux:eq:global-halfturn}
\end{equation}

\label{flux:prop:finite-compiler}
Let \(D_2(\nu_0\Vert\pi)\le\Delta\), where \(\Delta\ge1\), and let
\(0<\varepsilon<1/4\).  For \(0<\eta\le1/\beta\), define
\[
 \ell=K\left\{\Delta+
 \log\left(\frac{Kd\kappa}{\varepsilon\alpha\eta}\right)\right\}.
\]
There are universal constants \(c,K>0\) such that, if
\begin{equation}
 s\{\sqrt{d\ell}+\ell\}\le c,
 \label{flux:eq:finite-gate}
\end{equation}
the finite flux algorithm returns \(\widehat X\) with
\(\operatorname{TV}(\operatorname{Law}(\widehat X),\pi)\le\varepsilon\) and
\begin{equation}
 \mathbb E N_{\mathrm{qry}}
 \le \frac K{\sqrt a}\sqrt{\log(\mathrm{e}/a)}
       \left(\Delta+\log\frac4\varepsilon\right)
       \left\{\log(\mathrm{e}\kappa\ell)
                    +s(\sqrt{d\ell}+\ell)\right\}.
 \label{flux:eq:fixed-scale-cost}
\end{equation}

\label{persistent:lem:row-identities}
The operator \(\mathsf K\) preserves \(\widehat\Pi_\eta\) and is a
contraction.  Moreover, for every \(f\in L^2(\widehat\Pi_\eta)\),
\begin{equation}
 \lVertf\rVert^2-\lVert\mathsf Kf\rVert^2
 \ge \rho\lVert\mathsf Qf\rVert^2.
 \label{persistent:eq:dissipation}
\end{equation}

\label{persistent:prop:three-side}
Let \(\mathcal H_+\) be the spectral subspace of \(\mathsf T\)
corresponding to \([1/2,1]\).  If \(\beta\eta\) is smaller than a universal
constant, then every \(f\in\mathcal H_+\) satisfies
\begin{align}
 &\lVert\mathsf S(\mathsf Q\mathsf U\mathsf P f)-M_f\rVert^2
 +\lVert\mathsf S M_f+\mathsf Q\mathsf U\mathsf P f\rVert^2
 +\lVert\mathsf U M_f-M_f\rVert^2 \notag\\
 &\hspace{35mm}\le
 C\lVert\Gamma f\rVert\lVert\Gamma^3f\rVert.
 \label{persistent:eq:three-side}
\end{align}

\label{persistent:lem:joint-quarter}
\label{prop:persistent-main-rotation}
If \(L_\eta:=\beta\eta\le1/2\), then, uniformly in \(y\),
\[
 \lVert\mathsf S\ell_{a,y}-m_a\rVert^2
 +\lVert\mathsf S m_a+\ell_{a,y}\rVert^2
 \le \frac{22L_\eta}{1-L_\eta}
       a^\mathrm{T} D_ya.
\]

\label{persistent:cor:factorized-errors}
Let \(\ell_g=1+\log(1/g)\).  There are bounded operators \(B_j\) such that
\begin{equation}
 F_j=B_j\Gamma,\qquad F_j^*=\Gamma B_j^*,\qquad
 \lVertB_j\rVert\le C\sqrt{\ell_g},\qquad j=1,2,3.
 \label{persistent:eq:factorized-errors}
\end{equation}

\label{persistent:prop:ideal-contraction}
Under the assumptions of \cref{thm:persistent-contraction}, choosing
\(\rho\asymp g\sqrt{\ell_g}\), where
\(g=\sqrt{\alpha\eta}\) and \(\ell_g=1+\log(1/g)\), gives
\begin{equation}
 \lVert\mathsf K^n\rVert_{L^2_0\to L^2_0}
 \le2\exp\left(-\frac{cng}{\sqrt{\ell_g}}\right).
 \label{eq:persistent-l2}
\end{equation}

\label{persistent:lem:resolvent}
If \(\rho\asymp g\sqrt{\ell_g}\), then
\[
 \sup_{\lvertz\rvert=1}
 \lVert(z-\mathsf K)^{-1}\rVert_{L^2_0\to L^2_0}
 \le \frac{C\sqrt{\ell_g}}{g}.
\]

\label{prop:warm-removal-posteriors}
Fix a law \(\nu\) with \(D_2(\nu\Vert\pi)\le B\), draw
\(X\sim\nu\) and, independently, a standard Gaussian vector
\(G\sim\mathcal N(0,I_d)\), where \(I_d\) is the \(d\)-dimensional identity; set
\(Y=X+\sqrt uG\), and denote the law of \(Y\) by
\(\lambda\).  Suppose \(u\le1/\alpha\).  For every \(0<\delta<1/2\),
each of the two interfaces above gives a jointly measurable, work-capped
kernel \(y\mapsto\widehat P_y\) such that
\begin{equation}
 \int\operatorname{TV}(\widehat P_y,q_y)\,\lambda(\mathrm{d} y)\le\delta.
 \label{eq:warm-removal-posterior-error}
\end{equation}
For the regular interface, every call uses at most
\begin{equation}
 C_{\rm reg}(K_u,d)
 :=K_u^{7/6}d^{1/6}+K_u^{1/2}d^{1/4}
 \label{eq:warm-removal-regular-posterior}
\end{equation}
oracle queries up to factors logarithmic in \(d,K_u,B,1/\delta\).  For the
HB interface, the corresponding bound is
\begin{equation}
 C_{\rm HB}(K_u,d):=1+K_u^{2/3}d^{1/3}
 \label{eq:warm-removal-harmonic-posterior}
\end{equation}
oracle queries, again up to the same type of logarithmic factors.

\label{prop:warm-removal-capped-finalizer}
Fix \(B\ge1\) and \(0<\varepsilon,\xi<1/2\).  Either reflected sampler admits an
implementable realization as a total Markov kernel
\(\widehat K_{B,\varepsilon,\xi}\) such that,
for every \(\nu\) satisfying \(D_2(\nu\Vert\pi)\le B\),
\(\operatorname{TV}(\nu\widehat K_{B,\varepsilon,\xi},\pi)\le\varepsilon+\xi\).  Up to logarithmic
factors, the kernel uses at most
\begin{equation}
 \widetilde O\!\left(
 \sqrt\kappa B(\sqrt{dB}+B)^{1/2}\right)
 \label{eq:warm-removal-finalizer}
\end{equation}
oracle queries.  In particular, constant \(B\) costs
\(\widetilde O(\sqrt\kappa d^{1/4})\).  The same kernel may be applied to a
second, arbitrary input law: its deterministic work bound remains valid,
and total-variation distance between the two inputs cannot increase.

\label{lem:warm-removal-hypercontractivity}
For every density \(f=\mathrm{d}\nu/\mathrm{d}\pi\), every \(p>1\), and every \(u>0\),
\[
 \lVertS_uf\rVert_{1+(1+\alpha u)^2(p-1)}\le\lVertf\rVert_p.
\]
Consequently, if \(G_m=\prod_{j=1}^m(1+\alpha u_j)\), then
\begin{equation}
 D_2(\nu S_{u_1}\cdots S_{u_m}\Vert\pi)
 \le\frac{2D_2(\nu\Vert\pi)}{1+G_m^2}.
 \label{eq:warm-removal-d2-conversion}
\end{equation}
